mkdir -p /tmp/edge && cd /tmp/edge && cat > edge.cpp <<'EOF'
#include "gigasecond.h"
#include <iostream>
using namespace boost::posix_time;
int main() {
    // leap-day start
    ptime a = time_from_string("2016-02-29 12:00:00");
    std::cout << "leap: " << gigasecond::advance(a) << "\n";
    // epoch
    ptime b = time_from_string("1970-01-01 00:00:00");
    std::cout << "epoch: " << gigasecond::advance(b) << "\n";
    // far future (post-2038 safety)
    ptime c = time_from_string("2038-01-19 03:14:07");
    std::cout << "2038: " << gigasecond::advance(c) << "\n";
    // century leap rule (2100 not leap)
    ptime d = time_from_string("2100-02-28 23:59:59");
    std::cout << "2100: " << gigasecond::advance(d) << "\n";
    // check exact delta in seconds
    std::cout << "delta_ok: " << ((gigasecond::advance(b) - b).total_seconds() == 1000000000LL) << "\n";
    return 0;
}
EOF
